import { getSQLDate } from '@helpers/dateHelper';
import { get, handleApiError, post } from '@helpers/httpClient';

import {
  mapBackHikingFoodToFront,
  mapBackHikingMenuProductToFront,
  mapHikingMenuActsToFront,
} from '../@mappers/hikingMenu.mapper';
import {
  IFoodActsRecipeCategory,
  IFoodLoadDto,
  IHikingMenuProductDTO,
} from '../@types/DTO/hikingMenu.dto.types';
import {
  IFoodActDTO,
  IHikingMenuActsByDays,
  IHikingMenuExtendedProduct,
  IHikingMenuFood,
} from '../@types/hikingMenu.types';
import {
  IProductForPrint,
  mapStickerToFront,
} from '../menu/components/HikingMenuPrintStickers/mapper';
export async function getHikingMenuActs(id_hiking: number): Promise<IHikingMenuActsByDays[]> {
  const acts = await get('/ajax/hiking/menu/acts.php', {
    id_hiking,
  }).then<IFoodActDTO[]>(handleApiError);

  return mapHikingMenuActsToFront(acts);
}

export interface IGetFoodLoadCriteria {
  id_hiking: number;
  date?: string;
  id_act?: number;
}
export async function getFoodAsync(criteria: IGetFoodLoadCriteria): Promise<IHikingMenuFood[]> {
  try {
    const acts = await get<IFoodLoadDto[], IGetFoodLoadCriteria>(
      '/ajax/hiking/menu/food_load.php',
      criteria,
    ).then<IFoodLoadDto[]>(handleApiError);

    return acts.map(mapBackHikingFoodToFront);
  } catch (e) {
    return Promise.reject((e as Error).message);
  }
}

export async function getHikingMenuProductsAsync(
  id_hiking: number,
): Promise<IHikingMenuExtendedProduct[]> {
  try {
    const pdts = await get<IHikingMenuProductDTO[]>('/ajax/hiking/menu/products.php', {
      id_hiking,
    }).then<IHikingMenuProductDTO[]>(handleApiError);

    return pdts.map(mapBackHikingMenuProductToFront);
  } catch (e) {
    return Promise.reject((e as Error).message);
  }
}

export interface IHikingFoodPatch {
  id_hiking: number;

  id?: number | number[];
  id_act?: number;
  date?: string;
  сorrection_coeff_pct?: number;
  assignee?: number;
  confirm?: boolean;

  /** @deprecated \
   * @since 2023 */
  is_optimize?: boolean;
}

export async function saveFoodPatchAsync(patch: IHikingFoodPatch) {
  try {
    const acts = await post('/ajax/hiking/menu/food_edit.php', { ...patch }).then(handleApiError);

    return acts;
  } catch (e) {
    return Promise.reject((e as Error).message);
  }
}

export async function saveFoodPatchByIdAsync(id: number | number[], patch: IHikingFoodPatch) {
  return saveFoodPatchAsync({ id, ...patch });
}

export async function deleteFoodByIdAsync(id: number) {
  try {
    const acts = await post('/ajax/hiking/menu/food_del.php', { id }).then(handleApiError);

    return acts;
  } catch (e) {
    return Promise.reject((e as Error).message);
  }
}

export interface IAddFoodPayload {
  id_hiking: number;
  id_recipe: number;
  id_act: number;
  date: Date;
}

interface IFoodAddResult {
  id: string;
}

export async function addFoodAsync(data: IAddFoodPayload): Promise<number> {
  try {
    const res = await post<IFoodAddResult>('/ajax/hiking/menu/food_add.php', {
      ...data,
      date: getSQLDate(data.date).substring(0, 10),
    }).then((x) => handleApiError<IFoodAddResult>(x));

    return Number(res.id);
  } catch (e) {
    return Promise.reject((e as Error).message);
  }
}

interface IProductForceAddPayload {
  id_hiking: number;
  id_user: number;
  id_product: number;
}

interface IProductForceResult {
  id: string;
}

export async function productForceAddAsync({
  id_hiking,
  id_user,
  id_product,
}: IProductForceAddPayload): Promise<number> {
  try {
    const res = await post<IProductForceResult, IProductForceAddPayload>(
      '/ajax/hiking/menu_user_product_force_add.php',
      { id_hiking, id_user, id_product },
    ).then((x) => handleApiError<IProductForceResult>(x));

    return Number(res.id);
  } catch (e) {
    return Promise.reject((e as Error).message);
  }
}

export async function productForceDelAsync(id_force: number): Promise<boolean> {
  try {
    await post('/ajax/hiking/menu_user_product_force_del.php', { id: id_force }).then(
      handleApiError,
    );

    return true;
  } catch (e) {
    return Promise.reject((e as Error).message);
  }
}

export async function getHikingProductsForPrint(
  id_hiking: number,
  additionalCriteria: { id_user?: number; date?: string; id_product?: number } = {},
): Promise<IProductForPrint[]> {
  try {
    const res = await get('/ajax/hiking/menu/products_print.php', {
      id_hiking,
      ...additionalCriteria,
    }).then(handleApiError);

    return res.map(mapStickerToFront);
  } catch (e) {
    return Promise.reject((e as Error).message);
  }
}

