import { IFoodLoadDto, IHikingMenuProductDTO } from '../@types/DTO/hikingMenu.dto.types';
import { IFoodAct } from '../@types/hiking.baseTypes';
import {
  IFoodActDTO,
  IHikingMenuActsByDays,
  IHikingMenuExtendedProduct,
  IHikingMenuFood,
  IHikingMenuFoodWithAct,
  IHikingMenuProductUsage,
} from '../@types/hikingMenu.types';

export function mapBackHikingFoodToFront(backModel: IFoodLoadDto): IHikingMenuFood {
  return {
    id: +backModel.id,
    name: backModel.name,
    date: new Date(backModel.date),
    id_act: +backModel.id_act,
    id_recipe: +backModel.id_recipe,
    correction: +backModel.сorrection_coeff_pct / 100,
    text: backModel.text,
    energy: +backModel.energy,
    amount: +backModel.amount,
    proteins: +backModel.protein,
    fats: +backModel.fat,
    carbs: +backModel.carbohydrates,
    water_count: backModel.water_count ? +backModel.water_count : null,
    gas_count: backModel.gas_count ? +backModel.gas_count : null,
    cooking_time: backModel.cooking_time ? +backModel.cooking_time : null,
    assigneeUser: !backModel.uid
      ? null
      : {
          id: +backModel.uid,
          name: backModel.uname ?? '',
          photo: backModel.uphoto ?? '',
        },
    confirmUser: backModel.confirm_user ?? null,
    confirmDate: backModel.confirm_date ? new Date(backModel.confirm_date) : null,
    products: backModel.products.split('&').map((s: string) => {
      const [id, name, amount, original_id, original_name, replace_rate] = s.split('|');
      return {
        id: +id,
        name,
        amount: +amount,
        ex:
          id === original_id
            ? undefined
            : {
                id: +original_id,
                name: original_name,
                rate: +replace_rate,
              },
      };
    }),
  };
}

export function mapBackHikingMenuProductToFront(
  backModel: IHikingMenuProductDTO,
): IHikingMenuExtendedProduct {
  return {
    id: +backModel.id_product,
    name: backModel.name,
    amount: +backModel.amount,

    ex:
      backModel.id_product === backModel.original_id_product
        ? undefined
        : {
            name: backModel.original_name,
            id: +backModel.original_id_product,
            rate: +backModel.replace_rate,
          },

    idForce: backModel.id_force ? +backModel.id_force : undefined,
    forcedUser: backModel.forceUserId
      ? {
          id: +backModel.forceUserId,
          name: backModel.forceUserName!,
          photo: backModel.forceUserPhoto!,
        }
      : null,
    usages: backModel.usages.map<IHikingMenuProductUsage>((u) => ({
      name: u.name,
      act: {
        id: +u.schedule.id_food_act,
        name: u.schedule.name,
      },
      amount: +u.amount,
      d1: new Date(u.schedule.d1),
      d2: new Date(u.schedule.d2),
      is_self_sufficiency: u.schedule.is_self_sufficiency == '1',
      assigneeUser: u.assigneeUser
        ? {
            id: +u.assigneeUser.id!,
            name: u.assigneeUser.name!,
            photo: u.assigneeUser.photo!,
          }
        : null,
    })),
  };
}

export const includeActInfo =
  (acts: IHikingMenuActsByDays[]) =>
  (food: IHikingMenuFood): IHikingMenuFoodWithAct => ({
    ...food,
    act:
      acts
        .find((a) => a.date.toLocaleDateString() === food.date.toLocaleDateString())
        ?.acts?.find((x) => x.id === food.id_act) || null,
  });

const mapHikingMenuActToFront = (backData: IFoodActDTO): IFoodAct => {
  return {
    id: +backData.id,
    name: backData.name,
    kkalCurrent: +backData.kkal,
    kkalTarget: +backData.norm_kkal,
    start: new Date(backData.d1),
    finish: new Date(backData.d2),
    is_self_sufficiency: backData.is_self_sufficiency == '1',
  };
};

export const mapHikingMenuActsToFront = (backData: IFoodActDTO[]): IHikingMenuActsByDays[] => {
  const daysMap: Record<string, IHikingMenuActsByDays> = {};

  backData.forEach((r) => {
    const d1 = new Date(r.d1);
    const k = d1.toISOString().substring(0, 10);
    if (!daysMap[k]) {
      daysMap[k] = {
        date: d1,
        acts: [],
      };
    }

    daysMap[k].acts.push(mapHikingMenuActToFront(r));
  });
  return Object.values(daysMap);
};
